mapper.select:
SELECT rv.id, rv.reservation_id AS reservationId, rv.verified_count AS verifiedCount, rv.scanner_code AS scannerCode, rv.result, rv.failure_reason AS failureReason, rv.verified_at AS verifiedAt FROM reservation_verification rv WHERE 1 = 1
AND rv.reservation_id = #{reservationVerification.reservationId}
AND rv.scanner_code LIKE CONCAT('%',#{reservationVerification.scannerCode},'%')
AND rv.result = #{reservationVerification.result}
ORDER BY rv.verified_at DESC
